// CSD_RATIONALE_BEGIN
// Root cause of all 141-142 mode_A failures identified from rollout examples:
// Phase 3 breaks immediately when parser.IsCompletePrefix(currentConstrainedOut)
// is true. For Spider SQL, `SELECT id FROM highschooler` and similar minimal
// fragments are parser-complete, so the loop exits after only ~7 tokens.
// But the correct answers need WHERE conditions, JOINs, GROUP BY, ORDER BY,
// LIMIT — requiring 20-60 more tokens. The early break was preventing these.
//
// Evidence: avg generated tokens = 8.67, median = 7.00 — exactly the length
// of a minimal SELECT...FROM statement. Removing the IsCompletePrefix early-exit
// lets the model continue until it naturally emits EOS or the 300-step budget
// is exhausted. ConstrainedStep still hard-masks to valid extensions at every
// step (WHERE, JOIN, ORDER BY etc. are valid extensions of a complete SQL
// prefix in most SQL parsers).
//
// Primary fix: Remove `if parser.IsCompletePrefix(...) { break; }` from Phase 3.
// Secondary fix: Update guidance to explicitly request complete SQL with all
//   required clauses (WHERE, JOIN, GROUP BY, ORDER BY, LIMIT).
// All other parameters unchanged from best attempt 66/61:
//   Phase 1: ≤5 unconstrained preamble steps.
//   Phase 2: OpenConstrainedSpan force.
//   Phase 3: ConstrainedStep loop, sqlBudget = min(remaining-1, 300).
//   Phase 4: CloseConstrainedSpan if complete, else CloseSpanWithinBudget(120).
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 (unconstrained loop): Loop guard requires !insideConstrainedOut, so
//   the implication is vacuously true throughout. The only true-flip is via
//   RenderedEndsWith check; at that point currentConstrainedOut := [] and
//   IsValidPrefix([]) holds by method precondition. EOS break leaves
//   insideConstrainedOut false (implication vacuous).
//
// Phase 2 (OpenConstrainedSpan): Runs only when !insideConstrainedOut.
//   Postcondition sets currentConstrainedOut := []; IsValidPrefix([]) holds
//   by method precondition.
//
// Phase 3 inner loop: ConstrainedStep postcondition guarantees
//   next == eosToken || IsTokenValidNext(parser, currentConstrainedOut, next).
//   When next != eosToken and IsTokenValidNext holds, AppendConstrainedToken
//   postcondition guarantees parser.IsValidPrefix(currentConstrainedOut + [next]).
//   EOS causes a break leaving currentConstrainedOut unchanged.
//   Removing the IsCompletePrefix break does not affect this: validity
//   maintenance depends only on ConstrainedStep + AppendConstrainedToken,
//   not on parser completeness status.
//
// Phase 4a (CloseConstrainedSpan): Sets insideConstrainedOut := false,
//   implication vacuously true; clears currentConstrainedOut := [].
// Phase 4b (CloseSpanWithinBudget): Postcondition directly guarantees
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep costs +1 step; appends 0 (EOS) or 1 (non-EOS)
//   token per iteration. 1:1 or better each iteration.
//
// Phase 2: OpenConstrainedSpan costs +1 step, appends exactly 1 "<<" token. 1:1.
//
// Phase 3 inner loop: ConstrainedStep costs +1 step per iteration
//   (sqlSteps += 1); AppendConstrainedToken appends at most 1 token
//   (EOS path appends 0). Loop invariant: |generated| <= |generatedPrefix|
//   + steps + sqlSteps. sqlBudget <= remaining - 1 ensures
//   steps + sqlSteps <= maxSteps - 1 after loop, leaving budget for Phase 4.
//   After loop: steps := steps + sqlSteps re-establishes outer invariant.
//
// Phase 4a: CloseConstrainedSpan costs +1 step, appends at most 1 ">>"
//   token. ≤1:1. Final steps <= maxSteps.
// Phase 4b: CloseSpanWithinBudget postcondition guarantees
//   |generatedOut| <= |generated| + closeBudget; steps += closeBudget <= remaining.
//   Invariant preserved by transitivity. Final steps <= maxSteps.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a valid SQL SELECT statement using ONLY the exact table and column names from the provided schema. Generate the COMPLETE SQL including all necessary WHERE conditions, JOINs, GROUP BY, ORDER BY, and LIMIT clauses as required by the question. The SQL must be placed between << and >>. No explanation, no markdown.");

var steps: nat := 0;

// Phase 1: Short preamble (at most 5 steps) to let model emit "SQL: <<"
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL via ConstrainedStep loop.
// KEY FIX: No early break on IsCompletePrefix. The previous code exited here
// after only ~7 tokens (minimal valid SQL like "SELECT id FROM tbl"). Spider
// queries need WHERE/JOIN/GROUP BY/ORDER BY/LIMIT. Let the model run until
// it naturally emits EOS or the 300-step budget is exhausted.
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var sqlBudget: nat;
  if remaining <= 1 {
    sqlBudget := 0;
  } else if remaining - 1 <= 300 {
    sqlBudget := remaining - 1;
  } else {
    sqlBudget := 300;
  }

  // constrainedPrompt = full context before constrained content.
  // As AppendConstrainedToken grows both generated and currentConstrainedOut
  // by 1 each step, |generated| - |currentConstrainedOut| stays constant.
  var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
  var sqlSteps: nat := 0;

  while sqlSteps < sqlBudget && insideConstrainedOut
    invariant 0 <= sqlSteps <= sqlBudget
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps + sqlSteps
    decreases sqlBudget - sqlSteps
  {
    var next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
    sqlSteps := sqlSteps + 1;
    if next == eosToken {
      break;
    } else {
      var valid := helpers.IsTokenValidNext(parser, currentConstrainedOut, next);
      if valid {
        var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }

  steps := steps + sqlSteps;
}

// Phase 4: Close the constrained span
if insideConstrainedOut && steps < maxSteps {
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    var remaining := maxSteps - steps;
    var closeBudget: nat;
    if remaining <= 120 {
      closeBudget := remaining;
    } else {
      closeBudget := 120;
    }
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + closeBudget;
  }
}

cost := steps;

